from flag_rollout import *

svc = FeatureFlagService()
svc.publish("f", 1, {"enabled": True, "default": False, "rules": [],
                     "rollout": {"percentage": 0, "salt": "s", "serve": True}})
subs = [{"subject_id": "u%d" % i} for i in range(40)]
svc.create_rollout_plan("f", [{"name": "a", "percentage": 50}])
# 错误预期 -> 冲突，不推进
try: svc.advance_rollout_plan("f", subs, set())
except RolloutConflictError: print("conflict ok")
print("current still:", svc.evaluate("f", {"subject_id":"u0"})["revision"])

# 非法阶段输入全拒
for bad in [[], [{}], [{"name":"a"}], [{"name":"a","percentage":True}],
            [{"name":"a","percentage":float("nan")}], [{"name":"a","percentage":0}],
            [{"name":"a","percentage":101}],
            [{"name":"a","percentage":10},{"name":"b","percentage":10}],
            [{"name":"a","percentage":20},{"name":"a","percentage":30}],
            [{"name":"","percentage":10}], 42, [{"name":"a","percentage":10,"extra":1}]]:
    try:
        svc.create_rollout_plan("f", bad); print("FAIL accepted:", bad)
    except (InvalidRolloutPlanError, RolloutPlanConflictError): pass
print("invalid stages rejected")

# advance 参数错误
try: svc.advance_rollout_plan("f", 42, set())
except InvalidRolloutChangeError: print("subjects ok")
try: svc.advance_rollout_plan("f", subs, 42)
except InvalidRolloutChangeError: print("expected ok")
try: svc.advance_rollout_plan("f", [{"subject_id":["x"]}], set())
except InvalidRolloutChangeError: print("unhashable ok")
try: svc.advance_rollout_plan("nope", [], set())
except FlagNotFoundError: print("unknown flag ok")

# 无计划 / 缺 subject
svc2 = FeatureFlagService()
svc2.publish("h", 1, {"enabled": True, "default": False, "rules": [],
                      "rollout": {"percentage": 0, "salt": "s", "serve": True}})
try: svc2.advance_rollout_plan("h", [], set())
except RolloutPlanStateError: print("no plan ok")
svc2.create_rollout_plan("h", [{"name":"a","percentage":100}])
try: svc2.advance_rollout_plan("h", [{}], set())
except MissingSubjectError: print("missing subject ok")
print("rev unchanged:", svc2.evaluate("h", {"subject_id":"u0"})["revision"],
      "plan not advanced:", end=" ")
try:
    svc2.advance_rollout_plan("h", [{"subject_id":"u0"}], set())  # 100% 影响 u0 与空预期冲突 -> 仍未推进
    print("unexpected success")
except RolloutConflictError:
    print("still on stage0")

# 未知 flag 创建计划
try: svc2.create_rollout_plan("zz", [{"name":"a","percentage":1}])
except FlagNotFoundError: print("create unknown flag ok")

# base percentage 非 0
svc2.publish("h", 2, {"enabled": True, "default": False, "rules": [],
                      "rollout": {"percentage": 30, "salt": "s", "serve": True}})
svc2._plans.clear()
p = svc2.create_rollout_plan("h", [{"name":"a","percentage":30.0001},{"name":"b","percentage":80}])
print("base:", p["baseRevision"], p["basePercentage"], p["stages"])

# 浮点非有限
for bad in (float("inf"), -float("inf"), float("nan"), True, "10", None):
    try:
        svc2._plans.clear()
        svc2.create_rollout_plan("h", [{"name":"z","percentage":bad}])
        print("FAIL", bad)
    except (InvalidRolloutPlanError, RolloutPlanConflictError): pass
print("finite check ok")
